 61→    public IndexService(String host, Integer port, String scheme, String esUsername, String esPassword) {
 62→        this.host = host;
 63→        this.port = port;
 64→        this.scheme = scheme;
 65→        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
 66→        if (esUsername != null && !"".equals(esUsername) && esPassword != null && !"".equals(esPassword)) {
 67→            credentialsProvider.setCredentials(AuthScope.ANY, new UsernamePasswordCredentials(esUsername, esPassword));
 68→            this.restClientBuilder = RestClient.builder(new HttpHost[]{new HttpHost(host, port, scheme)}).setHttpClientConfigCallback((httpClientBuilder) -> {
 69→                return httpClientBuilder.setDefaultCredentialsProvider(credentialsProvider).setKeepAliveStrategy(this.getConnectionKeepAliveStrategy());
 70→            });
 71→        } else {
 72→            this.restClientBuilder = RestClient.builder(new HttpHost[]{new HttpHost(host, port, scheme)})
 73→                    .setRequestConfigCallback(requestConfigBuilder -> requestConfigBuilder.setConnectTimeout(CONNECTION_TIMEOUT)
 74→                            .setSocketTimeout(SOCKET_TIMEOUT)).setHttpClientConfigCallback((httpClientBuilder) -> {
 75→                return httpClientBuilder.setKeepAliveStrategy(this.getConnectionKeepAliveStrategy());
 76→            });
 77→        }
 78→
 79→        this.restClientBuilder.setRequestConfigCallback((requestConfigBuilder) -> {
 80→            return requestConfigBuilder.setConnectTimeout(40000).setSocketTimeout(600000);
 81→        });
 82→        logger.info("host : {} , port : {}, scheme : {}, username: {}, password: {} ", new Object[]{host, port, scheme, esUsername, esPassword});
 83→    }
