130→    public void index(Ingester ingester, String index, Integer bulkSize, Filter filter, Job job, String pipeLine) throws CircuitBreakerException, Exception, StopSignalException {
131→        try (RestHighLevelClient client = new RestHighLevelClient(restClientBuilder)) {
132→            count = 0;
133→
134→            String id = "";
135→            long start = System.currentTimeMillis();
136→            BulkRequest request = new BulkRequest();
137→            long time = System.nanoTime();
138→            try {
139→                logger.info("index start!");
140→
141→                while (ingester.hasNext()) {
142→                    if (job != null && job.getStopSignal() != null && job.getStopSignal()) {
143→                        logger.info("Stop Signal");
144→                        throw new StopSignalException();
145→                    }
146→
147→                    Map<String, Object> record = ingester.next();
148→                    if (filter != null && record != null && record.size() > 0) {
149→                        record = filter.filter(record);
150→                    }
151→
152→                    //logger.info("{}", record);
153→                    if (record != null && record.size() > 0) {
154→                        count++;
155→
156→                        IndexRequest indexRequest = new IndexRequest(index).source(record, XContentType.JSON);
157→
158→                        if (record.get("ID") != null) {
159→                            id = record.get("ID").toString();
160→                        } else if (record.get("id") != null) {
161→                            id = record.get("id").toString();
162→                        }
163→
164→                        if (id.length() > 0) {
165→                            indexRequest.id(id);
166→                        }
167→
168→                        if (pipeLine.length() > 0) {
169→                            indexRequest.setPipeline(pipeLine);
170→                        }
171→
172→                        request.add(indexRequest);
173→                    }
174→
175→                    if (count % bulkSize == 0) {
176→                        int waitCount = 10;
177→                        int sleepTime = 30000;
178→
179→                        // 문서 손실 방지. es rejected 에러시 무한 색인 요청 -> 무한 색인에서 총 10회, 30초 대기로 변경(circuit breaker exception 오류)
180→                        while (true) {
181→                            if(waitCount == 0){
182→                                throw new CircuitBreakerException("서킷 브레이커 익셉션이 발생 하였습니다.");
183→                            }
184→
185→                            BulkResponse bulkResponse = client.bulk(request, RequestOptions.DEFAULT);
186→                            boolean isCircuitBreakerException = false; // 서킷 브레이커 익셉션 발생 판단
187→
188→                            if (bulkResponse.hasFailures()) {
189→                                BulkItemResponse[] bulkItemResponses = bulkResponse.getItems();
190→                                for (int i = bulkItemResponses.length - 1; i >= 0; i--) {
191→                                    BulkItemResponse bulkItemResponse = bulkItemResponses[i];
192→
193→                                    if (bulkItemResponse.isFailed()) {
194→                                        BulkItemResponse.Failure failure = bulkItemResponse.getFailure();
195→                                        // write queue reject 이슈 코드 = ( 429 )
196→                                        // 서킷 브레이커 익셉션 발생으로 판단
197→                                        if (failure.getStatus() == RestStatus.fromCode(429)) {
198→                                            logger.error("write queue rejected!! >> {}", failure);
199→                                            isCircuitBreakerException = true;
200→                                        } else {
201→                                            // 색인 시 형태소 분석 에러나 디스크 용량이 꽉 찼을 경우 에러 발생
202→                                            logger.error("Doc index error >> {}", failure);
203→
204→                                            // bulk request 에서 지워준다
205→                                            request.requests().remove(i);
206→                                        }
207→                                    }else{
208→                                        request.requests().remove(i);
209→                                    }
210→                                }
211→                            } else {
212→                                // bulk request에 대한 실패가 없음
213→                                request.requests().clear();
214→                            }
215→
216→                            if(isCircuitBreakerException){
217→                                // 서킷 브레이커 익셉션이 발생했을 경우
218→                                // 30초 대기, 10회
219→                                Thread.sleep(sleepTime);
220→                                waitCount--;
221→                                logger.info("Circuit Breaker Exception Count... {}", waitCount);
222→                                continue;
223→                            }
224→
225→                            if(request.requests().size() == 0) break;
226→
227→                            if (job.getStopSignal()) {
228→                                throw new StopSignalException();
229→                            }
230→                        }
231→                    }
232→
233→                    if (count != 0 && count % 10000 == 0) {
234→                        if (groupSeq != null) {
235→                            logger.info("GroupSeq: [{}], index: [{}] {} ROWS FLUSHED! in {}ms", groupSeq, index, count, (System.nanoTime() - time) / 1000000);
236→                        } else {
237→                            logger.info("index: [{}] {} ROWS FLUSHED! in {}ms", index, count, (System.nanoTime() - time) / 1000000);
238→                        }
239→                    }
240→                    //logger.info("{}",count);
241→                }
242→
243→                if (request.requests().size() > 0) {
244→                    //나머지..
245→                    BulkResponse bulkResponse = client.bulk(request, RequestOptions.DEFAULT);
246→                    checkResponse(bulkResponse);
247→                    logger.info("Final bulk! {}", count);
248→                }
249→
250→            } catch (StopSignalException e) {
251→                throw e;
252→            } catch (CircuitBreakerException e){
253→                throw e;
254→            } catch (Exception e) {
255→                logger.error("Error occur! => ", e);
256→
257→                // 에러가 났을 경우 request 안의 id와 type을 10 개만 찍는다
258→                List<DocWriteRequest<?>> list = request.requests();
259→                int errorCount = list.size() < 10 ? list.size() : 10;
260→                for(int i = 0 ;i < errorCount; i++){
261→                    DocWriteRequest docWriteRequest = list.get(i);
262→                    logger.error("request => ", docWriteRequest.id(), docWriteRequest.type());
263→                }
264→                throw e;
265→            }
266→
267→            long totalTime = System.currentTimeMillis() - start;
268→            if (groupSeq != null) {
269→                logger.info("GroupSeq: [{}], index:[{}] Flush Finished! doc[{}] elapsed[{}m]", groupSeq, index, count, totalTime / 1000 / 60);
270→            } else {
271→                logger.info("index:[{}] Flush Finished! doc[{}] elapsed[{}m]", index, count, totalTime / 1000 / 60);
272→            }
273→        }
274→    }
