276→    /*
277→    * reindex 전체색인을 위한 메소드
278→     */
279→    public void reindex(Map<String, Object> payload, String destIndex, Job job) throws Exception {
280→        // dest로 source를 구함
281→        String sourceIndex = destIndex.endsWith("-a") ? destIndex.replace("-a", "-b") : destIndex.replace("-b", "-a"); // 목적지 인덱스
282→        String slices = (String) payload.get("slices");
283→        String size = (String) payload.get("size");
284→        String reindexCheckMs = (String) payload.get("reindexCheckIntervalMs");
285→        String replicaCheckMs = (String) payload.get("replicaCheckIntervalMs");
286→        String reindexFinishAndWaitMs = (String) payload.get("reindexFinishAndWaitMs");
287→        String pipeLine = (String) payload.getOrDefault("pipeLine", "");
288→
289→        try (RestHighLevelClient client = new RestHighLevelClient(restClientBuilder)) {
290→            long start = System.currentTimeMillis();
291→            try {
292→                // 레플리카를 0으로 바꾸기 전 셋팅 가져오기
293→                int replicaCount = getIndexReplicaSetting(client, destIndex);
294→
295→                // 대상 인덱스 replica 셋팅 0으로 변경
296→                modifyReplica(client, destIndex, 0);
297→
298→                // reindex 작업 시작
299→                String taskId = executeReindex(client, sourceIndex, destIndex, slices, size, pipeLine);
300→
301→                // reindex가 끝났는지 반복 확인
302→                try {
303→                    while (!isTaskDone(client, taskId)) {
304→                        if (job != null && job.getStopSignal() != null && job.getStopSignal()) {
305→                            logger.info("Stop Signal");
306→                            throw new StopSignalException();
307→                        }
308→
309→                        Thread.sleep(Long.parseLong(reindexCheckMs));
310→                    }
311→                } catch (Exception e) {
312→                    // 에러 발생 시 작업을 취소한다
313→                    cancelReindexTask(client, taskId);
314→                    throw e;
315→                }
316→
317→                // reindex 후 대기 시간
318→                logger.info("reindex Finished! wait [{}m]", Long.parseLong(reindexFinishAndWaitMs) / 1000 / 60);
319→
320→                Thread.sleep(Long.parseLong(reindexFinishAndWaitMs));
321→
322→                // 레플리카 생성 시작
323→                modifyReplica(client, destIndex, replicaCount);
324→
325→                // 레플리카 생성 후 잠깐 대기 10초
326→                Thread.sleep(10000);
327→
328→                // 레플리카 생성이 끝났는지 반복 확인
329→                while (!isIndexGreen(client, destIndex)) {
330→                    if (job != null && job.getStopSignal() != null && job.getStopSignal()) {
331→                        logger.info("Stop Signal");
332→                        throw new StopSignalException();
333→                    }
334→
335→                    Thread.sleep(Long.parseLong(replicaCheckMs));
336→                }
337→
338→            } catch (StopSignalException e) {
339→                logger.error("Process Stop! => ", e);
340→                throw e;
341→            } catch (Exception e) {
342→                logger.error("Error occur! => ", e);
343→                throw e;
344→            }
345→
346→            long totalTime = System.currentTimeMillis() - start;
347→            logger.info("index:[{}] reindex Finished! doc[{}] elapsed[{}m]", destIndex, count, totalTime / 1000 / 60);
348→        }
349→    }
