351→    private int getIndexReplicaSetting(RestHighLevelClient client, String index) {
352→        int count = 0;
353→        for (int i = 0; i <= MAX_RETRIES_COUNT; i++) {
354→            try{
355→                RestClient restClient = client.getLowLevelClient();
356→                Request request = new Request(
357→                        "GET",
358→                        index + "/_settings");
359→                Response response = restClient.performRequest(request);
360→                String responseBody = EntityUtils.toString(response.getEntity());
361→
362→                // 다중으로 존재하므로 아래와 같이 파싱..
363→                JSONObject jsonObj = new JSONObject(responseBody);
364→                JSONObject targetIndex = jsonObj.getJSONObject(index);
365→                JSONObject settings = targetIndex.getJSONObject("settings");
366→                JSONObject config = settings.getJSONObject("index");
367→                count = config.getInt("number_of_replicas");
368→                logger.info("TARGET_INDEX_REPLICA_COUNT : {}", count);
369→                break;
370→            } catch (Exception e) {
371→                // 예외 처리
372→                logger.error("GET_REPLICA_SETTING_FAIL. {} RETRY : {}", e, i);
373→                try {
374→                    // 재시도하기 전에 3분 동안 휴면
375→                    Thread.sleep(RETRY_INTERVAL_MS * 180);
376→                } catch (Exception ignore){}
377→                // 마지막 재시도가 실패하면 예외를 던진다.
378→                if (i == MAX_RETRIES_COUNT) {
379→                    throw new RuntimeException("GET_SETTING_FAIL_ERROR", e);
380→                }
381→            }
382→        }
383→        return count;
384→    }
