386→    // reindex API
387→    private String executeReindex(RestHighLevelClient client, String sourceIndex, String destIndex, String slices, String size, String pipeLine) throws Exception {
388→        String taskId = null;
389→        String entityPipeLine = "";
390→
391→        if (!pipeLine.equals("")) {
392→            entityPipeLine = ", \"pipeline\" : \"" + pipeLine + "\"\n";
393→        }
394→
395→        for (int i = 0; i <= MAX_RETRIES_COUNT; i++) {
396→            try{
397→                RestClient restClient = client.getLowLevelClient();
398→
399→                // reindex API 호출
400→                Request request = new Request(
401→                        "POST",
402→                        "/_reindex");
403→                request.addParameter("wait_for_completion", "false");
404→                request.addParameter("slices", slices);
405→                String entity = "{\n" +
406→                        "  \"source\": {\n" +
407→                        "    \"index\": \"" + sourceIndex + "\",\n" +
408→                        "    \"size\": " + Integer.valueOf(size) + "\n" +
409→                        "  }, \n" +
410→                        "  \"dest\": {\n" +
411→                        "    \"index\": \"" + destIndex + "\"\n" +
412→                               entityPipeLine +
413→                        "  } \n" +
414→                        "}";
415→                logger.info(entity);
416→                request.setJsonEntity(entity);
417→                Response response = restClient.performRequest(request);
418→                String responseBody = EntityUtils.toString(response.getEntity());
419→                JSONObject jsonObj = new JSONObject(responseBody);
420→                logger.info("REINDEX_START : {}, SOURCE_INDEX : {}, DEST_INDEX : {}, SLICES : {}, SIZE : {}", jsonObj, sourceIndex, destIndex, slices, size);
421→                if(jsonObj.get("task") != null){
422→                    taskId = (String) jsonObj.get("task");
423→                }
424→                break;
425→            } catch (Exception e) {
426→                // 예외 처리
427→                logger.error("EXECUTE_REINDEX_FAIL. {} RETRY : {}", e, i);
428→                // 재시도하기 전에 1초 동안 휴면
429→                Thread.sleep(RETRY_INTERVAL_MS);
430→                // 마지막 재시도가 실패하면 예외를 던진다.
431→                if (i == MAX_RETRIES_COUNT) {
432→                    throw new RuntimeException("REINDEX_EXECUTE_ERROR : ", e);
433→                }
434→            }
435→        }
436→        return taskId;
437→    }
