439→    // reindex cancel API
440→    private void cancelReindexTask(RestHighLevelClient client, String taskId) throws Exception {
441→        for (int i = 0; i <= MAX_RETRIES_COUNT; i++) {
442→            try{
443→                RestClient restClient = client.getLowLevelClient();
444→                Request request = new Request(
445→                        "POST",
446→                        "_tasks/" + taskId +"/_cancel");
447→                Response response = restClient.performRequest(request);
448→                String responseBody = EntityUtils.toString(response.getEntity());
449→                JSONObject jsonObj = new JSONObject(responseBody);
450→                logger.info("REINDEX_CANCEL : {}, TASK_ID : {}", jsonObj, taskId);
451→                break;
452→            } catch (Exception e) {
453→                // 예외 처리
454→                logger.error("CANCEL_REINDEX_FAIL. {} RETRY : {}", e, i);
455→                // 재시도하기 전에 1초 동안 휴면
456→                Thread.sleep(RETRY_INTERVAL_MS);
457→                // 마지막 재시도가 실패하면 예외를 던진다.
458→                if (i == MAX_RETRIES_COUNT) {
459→                    throw new Exception("REINDEX_CANCEL_ERROR : ", e);
460→                }
461→            }
462→        }
463→    }
