496→    private boolean isIndexGreen(RestHighLevelClient client, String index) throws Exception {
497→        boolean result = false;
498→        for (int i = 0; i <= MAX_RETRIES_COUNT; i++) {
499→            try{
500→                if(index != null){
501→                    RestClient restClient = client.getLowLevelClient();
502→                    Request request = new Request(
503→                            "GET",
504→                            "/"+ index + "/_shard_stores/");
505→                    Response response = restClient.performRequest(request);
506→                    String responseBody = EntityUtils.toString(response.getEntity());
507→                    JSONObject jsonObj = new JSONObject(responseBody);
508→
509→                    // 결과값이 없을때 Green 상태 processing false.
510→                    result = jsonObj.get("indices").toString().equals("{}");
511→                }
512→                break;
513→            } catch (Exception e) {
514→                // 예외 처리
515→                logger.error("CHECK_INDEX_GREEN_FAIL. {} RETRY : {}", e, i);
516→                // 재시도하기 전에 3분 동안 휴면
517→                Thread.sleep(RETRY_INTERVAL_MS * 180);
518→                // 마지막 재시도가 실패하면 예외를 던진다.
519→                if (i == MAX_RETRIES_COUNT) {
520→                    throw new Exception("CHECK_INDEX_GREEN_ERROR : ", e);
521→                }
522→            }
523→        }
524→        return result;
525→    }
