527→    private boolean isTaskDone(RestHighLevelClient client, String taskId) throws Exception {
528→        boolean result = false;
529→        for (int i = 0; i <= MAX_RETRIES_COUNT; i++) {
530→            try{
531→                if(taskId != null){
532→                    RestClient restClient = client.getLowLevelClient();
533→                    Request request = new Request(
534→                            "GET",
535→                            "/_tasks/" + taskId);
536→                    Response response = restClient.performRequest(request);
537→                    String responseBody = EntityUtils.toString(response.getEntity());
538→                    JSONObject jsonObj = new JSONObject(responseBody);
539→
540→                    // 한건이라도 실패하면 작업 중단
541→                    if(jsonObj.opt("response") != null){
542→                        JSONObject res = (JSONObject)jsonObj.get("response");
543→                        JSONArray failures  = (JSONArray)res.get("failures");
544→                        if(failures.length() > 0){
545→                            throw new Exception("Reindex Failure ERROR");
546→                        }
547→                    }
548→
549→                    result = ((boolean) jsonObj.get("completed"));
550→                }
551→                break;
552→            } catch (Exception e) {
553→                // 예외 처리
554→                logger.error("TASK_CHECK_FAIL. {} RETRY : {}", e, i);
555→                // 재시도하기 전에 3분 동안 휴면
556→                Thread.sleep(RETRY_INTERVAL_MS * 180);
557→                // 마지막 재시도가 실패하면 예외를 던진다.
558→                if (i == MAX_RETRIES_COUNT) {
559→                    throw new Exception("TASK_CHECK_FAIL ERROR : ",  e);
560→                }
561→            }
562→        }
