566→    class Worker implements Callable {
567→        private BlockingQueue queue;
568→        private int sleepTime = 30000;
569→        private String index;
570→        private Job job;
571→
572→        public Worker(BlockingQueue queue, String index, Job job) {
573→            this.queue = queue;
574→            this.index = index;
575→            this.job = job;
576→        }
577→
578→        private void retry(BulkRequest bulkRequest) {
579→            // 동기 방식
580→            BulkResponse bulkResponse = null;
581→
582→            try (RestHighLevelClient client = new RestHighLevelClient(restClientBuilder)) {
583→                // 문서 손실 방지. es rejected 에러시 무한 색인 요청 -> 무한 색인에서 총 10회, 30초 대기로 변경(circuit breaker exception 오류)
584→                int waitCount = 10;
585→
586→                while (true) {
587→                    if(waitCount == 0){
588→                        throw new CircuitBreakerException("서킷 브레이커 익셉션이 발생했습니다.");
589→                    }
590→
591→                    bulkResponse = client.bulk(bulkRequest, RequestOptions.DEFAULT);
592→                    boolean isCircuitBreakerException = false; // 서킷 브레이커 익셉션 발생 판단
593→
594→                    if (bulkResponse.hasFailures()) {
595→                        BulkItemResponse[] bulkItemResponses = bulkResponse.getItems();
596→                        // 각 인덱스 리퀘스트 별 리스폰스 분석
597→                        for (int i = bulkItemResponses.length - 1; i >= 0 ; i--) {
598→                            BulkItemResponse bulkItemResponse = bulkItemResponses[i];
599→                            if (bulkItemResponse.isFailed()) {
600→                                BulkItemResponse.Failure failure = bulkItemResponse.getFailure();
601→
602→                                // write queue reject 이슈 코드 = ( 429 )
603→                                // 서킷 브레이커 익셉션 발생으로 판단
604→                                if (failure.getStatus() == RestStatus.fromCode(429)) {
605→                                    logger.error("write queue rejected!! >> {}", failure);
606→                                    isCircuitBreakerException = true;
607→                                } else {
608→                                    // 색인 시 형태소 분석 에러나 디스크 용량이 꽉 찼을 경우 에러 발생
609→                                    logger.error("Doc index error >> {}", failure);
610→
611→                                    // bulk request 에서 지워준다
612→                                    bulkRequest.requests().remove(i);
613→                                }
614→                            }else{
615→                                // 실제로 색인이 된 리퀘스트는 제외 한다.
616→                                bulkRequest.requests().remove(i);
617→                            }
618→                        }
619→                    }else{
620→                        // 정상적으로 성공됨
621→                        bulkRequest.requests().clear();
622→                    }
623→
624→                    if(isCircuitBreakerException){
625→                        // 서킷 브레이커 익셉션이 발생했을 경우
626→                        // 30초 대기, 10회
627→                        Thread.sleep(sleepTime);
628→                        waitCount--;
629→                        logger.info("Circuit Breaker Exception Count... {}", waitCount);
630→                        continue;
631→                    }
632→
633→                    if(bulkRequest.requests().size() == 0) break;
634→
635→                    if (job.getStopSignal()) {
636→                        throw new StopSignalException();
637→                    }
638→                }
639→            } catch (Exception e) {
640→                // exception 발생 시 무한 색인 요청(while)을 빠져나간다.
641→                logger.error(e.getMessage());
642→            }
643→            logger.debug("Bulk Success : index:{} - count:{}, - elapsed:{}", index, count, bulkResponse.getTook());
644→        }
645→
646→
647→        @Override
648→        public Object call() {
649→            try {
650→                while (true) {
651→                    Object o = queue.take();
652→                    if (o instanceof String) {
653→                        //종료.
654→                        logger.info("Indexing Worker-{} index={} got {}", Thread.currentThread().getId(),index,o);
655→                        break;
656→                    }
657→                    BulkRequest request = (BulkRequest) o;
658→                    retry(request);
659→                    logger.debug("remained queue : {}", queue.size());
660→                }
661→            } catch (Throwable e) {
662→                logger.error("indexParallel : {}", e);
663→            }
664→            return null;
665→        }
666→    }
