672→    public void indexParallel(Ingester ingester, String index, Integer bulkSize, Filter filter, int threadSize, Job job, String pipeLine) throws IOException, StopSignalException, InterruptedException {
673→        ExecutorService executorService = Executors.newFixedThreadPool(threadSize);
674→
675→        BlockingQueue queue = new LinkedBlockingQueue(threadSize * 10);
676→        //여러 쓰레드가 작업큐를 공유한다.
677→        List<Future> list = new ArrayList<>();
678→        for (int i = 0; i < threadSize; i++) {
679→            Worker w = new Worker(queue, index, job);
680→            list.add(executorService.submit(w));
681→        }
682→
683→        String id = "";
684→        count = 0;
685→        long start = System.currentTimeMillis();
686→        BulkRequest request = new BulkRequest();
687→        long time = System.nanoTime();
688→        try {
689→            while (ingester.hasNext()) {
690→                if (job != null && job.getStopSignal() != null && job.getStopSignal()) {
691→                    logger.info("Stop Signal");
692→                    throw new StopSignalException();
693→                }
694→
695→                Map<String, Object> record = ingester.next();
696→
697→                //logger.info("record : {}" ,record.size());
698→
699→                if (filter != null && record != null && record.size() > 0) {
700→                    record = filter.filter(record);
701→                }
702→
703→                if (record != null && record.size() > 0) {
704→                    count++;
705→
706→                    IndexRequest indexRequest = new IndexRequest(index).source(record, XContentType.JSON);
707→
708→                    //_id 자동생성이 아닌 고정 필드로 색인
709→                    if (record.get("ID") != null) {
710→                        id = record.get("ID").toString();
711→                    } else if (record.get("id") != null) {
712→                        id = record.get("id").toString();
713→                    }
714→
715→                    if (id.length() > 0) {
716→                        indexRequest.id(id);
717→                    }
718→
719→                    if (pipeLine.length() > 0) {
720→                        indexRequest.setPipeline(pipeLine);
721→                    }
722→
723→                    request.add(indexRequest);
724→                }
725→
726→                if (count % bulkSize == 0) {
727→                    queue.put(request);
728→
729→//                    BulkResponse bulkResponse = client.bulk(request, RequestOptions.DEFAULT);
730→//                    logger.debug("bulk! {}", count);
731→
732→                    request = new BulkRequest();
733→                }
734→
735→                if (count % 100000 == 0) {
736→                    if (groupSeq != null) {
737→                        logger.info("groupSeq: [{}], index: [{}] {} ROWS FLUSHED! in {}ms", groupSeq, index, count, (System.nanoTime() - time) / 1000000);
738→                    } else {
739→                        logger.info("index: [{}] {} ROWS FLUSHED! in {}ms", index, count, (System.nanoTime() - time) / 1000000);
740→                    }
741→                }
742→            }
743→
744→            if (request.estimatedSizeInBytes() > 0) {
745→                //나머지..
746→                queue.put(request);
747→//                BulkResponse bulkResponse = client.bulk(request, RequestOptions.DEFAULT);
748→//                checkResponse(bulkResponse);
749→                logger.debug("Final bulk! {}", count);
750→            }
751→
752→
753→        } catch (InterruptedException e) {
754→            logger.error("interrupted! ", e);
755→            throw e;
756→        } catch (Exception e) {
757→            logger.error("[Exception] ", e);
758→            throw e;
759→        } finally {
760→            try {
761→                for (int i = 0; i < list.size(); i++) {
762→                    // 쓰레드 갯수만큼 종료시그널 전달.
763→                    queue.put("<END>");
764→                }
765→
766→            } catch (InterruptedException e) {
767→                logger.error("", e);
768→                //ignore
769→            }
770→
771→            try {
772→                for (int i = 0; i < list.size(); i++) {
773→                    Future f = list.get(i);
774→                    f.get();
775→                }
776→            } catch (Exception e) {
777→                logger.error("", e);
778→                //ignore
779→            }
780→
781→            // 큐 안의 내용 제거
782→            logger.info("queue clear");
783→            queue.clear();
784→
785→            // 쓰레드 종료
786→            logger.info("{} thread shutdown", index);
787→            executorService.shutdown();
788→
789→            // 만약, 쓰레드가 정상적으로 종료 되지 않는다면,
790→            if (!executorService.isShutdown()) {
791→                // 쓰레드 강제 종료
792→                logger.info("{} thread shutdown now!", index);
793→                executorService.shutdownNow();
794→            }
795→        }
796→
797→        long totalTime = System.currentTimeMillis() - start;
798→        if (groupSeq != null) {
799→            logger.info("GroupSeq: [{}],index:[{}] Flush Finished! doc[{}] elapsed[{}m]",groupSeq, index, count, totalTime / 1000 / 60);
800→        } else {
801→            logger.info("index:[{}] Flush Finished! doc[{}] elapsed[{}m]", index, count, totalTime / 1000 / 60);
802→        }
803→    }
