827→    public boolean retryUntilCreatingIndex(String index, Map<String, Object> indexSettings, int retryCount) throws IOException, InterruptedException {
828→        boolean result = false;
829→
830→        for (int r = 0; r < retryCount; r ++) {
831→            boolean isExistsIndex = existsIndex(index);
832→            logger.info("[{}] existsIndex: {}", index, isExistsIndex);
833→            if (isExistsIndex) {
834→                // 기존 인덱스가 존재할때 지우고 다시 생성
835→                boolean isDeleteIndex = deleteIndex(index);
836→                logger.info("[{}] isDeleteIndex: {}", index, isDeleteIndex);
837→                if(isDeleteIndex) {
838→                    if (createIndex(index, indexSettings)) {
839→                        // 생성 플래그값
840→                        result = true;
841→                        break;
842→                    }
843→                }
844→            } else {
845→                // 기존 인덱스가 없으면 생성
846→                if (createIndex(index, indexSettings)) {
847→                    // 생성 플래그값
848→                    result = true;
849→                    break;
850→                }
851→            }
852→            Thread.sleep(500);
853→        }
854→        return result;
855→    }
