 78→    public void executeQuery(int currentQueryListCount) throws IOException {
 79→
 80→        try {
 81→            if (currentQueryListCount > 0) {
 82→                connection = getConnection(driverClassName, url, user, password);
 83→            }
 84→
 85→            if (pstmt != null) {
 86→                pstmt.close();
 87→            }
 88→            logger.info("Num-{} QUERY Start", currentQueryListCount);
 89→            if (fetchSize < 0) {
 90→                //in mysql, fetch data row by row
 91→                pstmt = connection.prepareStatement(sqlList.get(currentQueryListCount), ResultSet.TYPE_FORWARD_ONLY, ResultSet.CONCUR_READ_ONLY);
 92→                pstmt.setFetchSize(Integer.MIN_VALUE);
 93→            } else {
 94→                pstmt = connection.prepareStatement(sqlList.get(currentQueryListCount));
 95→                if (fetchSize > 0) {
 96→                    pstmt.setFetchSize(fetchSize);
