293→                            file = readTmpClob(i, columnIdx, rsMeta, sb);
294→                            if (useBlobFile) {
295→                                keyValueMap.put(columnName[i], file);
296→                            } else {
297→                                keyValueMap.put(columnName[i], StringEscapeUtils.unescapeHtml(sb.toString()));
298→                            }
