346→    private File readTmpBlob(int columnInx, int columnNo, ResultSetMetaData rsMeta, OutputStream buffer) throws IOException, SQLException {
347→        File file = null;
348→        FileOutputStream os = null;
349→        InputStream is = null;
350→        try {
351→            is = r.getBinaryStream(columnNo);
352→            if (is != null) {
353→                if (buffer == null) {
354→                    file = File.createTempFile("blob." + columnNo, ".tmp");
355→                    os = new FileOutputStream(file);
356→                    // logger.debug("tmp file = "+f.getAbsolutePath());
357→                }
358→                for (int rlen = 0; (rlen = is.read(data, 0, data.length)) != -1; ) {
359→                    if (buffer != null) {
360→                        buffer.write(data, 0, rlen);
361→                    } else {
362→                        os.write(data, 0, rlen);
363→                    }
364→                }
365→            }
366→
367→        } catch (IOException e) {
368→            throw new IOException("Error while writing Blob field. column => " + rsMeta.getColumnName(columnNo));
369→        } finally {
370→            IOException ex = null;
371→            if (os != null)
372→                try {
373→                    os.close();
374→                } catch (IOException e) {
375→                    ex = e;
376→                }
377→            if (is != null)
378→                try {
379→                    is.close();
380→                } catch (IOException e) {
381→                    ex = e;
382→                }
383→            if (ex != null) {
384→                logger.error("Error while close LOB field and output file stream.", ex);
385→            }
386→        }
387→        return file;
388→    }
