390→    private File readTmpClob(int columnInx, int columnNo, ResultSetMetaData rsMeta, StringBuilder buffer) throws IOException, SQLException {
391→        File file = null;
392→        BufferedWriter os = null;
393→        BufferedReader is = null;
394→        try {
395→            Reader reader = r.getCharacterStream(columnNo);
396→            if (reader != null) {
397→                //buffer is null when using File
398→                if (buffer == null) {
399→                    file = File.createTempFile("clob." + columnNo, ".tmp");
400→                    os = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file)));
401→                }
402→                is = new BufferedReader(reader);
403→                for (String rline = ""; (rline = is.readLine()) != null; ) {
404→                    if (buffer != null) {
405→                        buffer.append(rline).append("\n");
406→                    } else {
407→                        os.write(rline);
408→                        os.write("\n");
409→                    }
410→                }
411→            }
412→        } catch (IOException e) {
413→            throw new IOException("Error while writing Clob field. column => " + rsMeta.getColumnName(columnNo));
414→        } finally {
415→            IOException ex = null;
416→            if (os != null) {
417→                try {
418→                    os.close();
419→                } catch (IOException e) {
420→                    ex = e;
421→                }
422→            }
423→            if (is != null) {
424→                try {
425→                    is.close();
426→                } catch (IOException e) {
427→                    ex = e;
428→                }
429→            }
430→            if (ex != null) {
431→                logger.error("Error while close clob field and output file stream.", ex);
432→            }
433→        }
434→        return file;
435→    }
