125→    public void executeQuery(int mainQueryListCount) throws IOException {
126→        try {
127→            if (mainQueryListCount > 0) {
128→                mainConnection = getConnection(driverClassName, url, user, password);
129→                subConnection = getConnection(subDriverClassName, subUrl, subUser, subPassword);
130→            }
