134→            }
135→
136→            if (subPstmt != null) {
137→                subPstmt.close();
138→            }
139→
140→            logger.info("Num-{} mainQuery Start", mainQueryListCount);
141→
142→            if (fetchSize < 0) {
143→                //in mysql, fetch data row by row
144→                mainPstmt = mainConnection.prepareStatement(mainSqlList.get(mainQueryListCount), ResultSet.TYPE_FORWARD_ONLY, ResultSet.CONCUR_READ_ONLY);
145→                mainPstmt.setFetchSize(Integer.MIN_VALUE);
146→            } else {
