508→    private File readTmpBlob(int columnInx, int columnNo, ResultSetMetaData rsMeta, OutputStream buffer) throws IOException, SQLException {
509→        File file = null;
510→        FileOutputStream os = null;
511→        InputStream is = null;
512→        try {
513→            is = mainRs.getBinaryStream(columnNo);
514→            if (is != null) {
515→                if (buffer == null) {
516→                    file = File.createTempFile("blob." + columnNo, ".tmp");
517→                    os = new FileOutputStream(file);
518→                }
519→                for (int rlen = 0; (rlen = is.read(data, 0, data.length)) != -1; ) {
520→                    if (buffer != null) {
521→                        buffer.write(data, 0, rlen);
522→                    } else {
523→                        os.write(data, 0, rlen);
524→                    }
525→                }
526→            }
527→
528→        } catch (IOException e) {
529→            throw new IOException("Error while writing Blob field. column => " + rsMeta.getColumnName(columnNo));
530→        } finally {
531→            IOException ex = null;
532→            if (os != null)
533→                try {
534→                    os.close();
535→                } catch (IOException e) {
536→                    ex = e;
537→                }
538→            if (is != null)
539→                try {
540→                    is.close();
541→                } catch (IOException e) {
542→                    ex = e;
543→                }
544→            if (ex != null) {
545→                logger.error("Error while close LOB field and output file stream.", ex);
546→            }
547→        }
548→        return file;
