551→    private File readTmpClob(int columnInx, int columnNo, ResultSetMetaData rsMeta, StringBuilder buffer) throws IOException, SQLException {
552→        File file = null;
553→        BufferedWriter os = null;
554→        BufferedReader is = null;
555→        try {
556→            Reader reader = mainRs.getCharacterStream(columnNo);
557→            if (reader != null) {
558→                //buffer is null when using File
559→                if (buffer == null) {
560→                    file = File.createTempFile("clob." + columnNo, ".tmp");
561→                    os = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file)));
562→                }
563→                is = new BufferedReader(reader);
564→                for (String rline = ""; (rline = is.readLine()) != null; ) {
