566→                        buffer.append(rline).append("\n");
567→                    } else {
568→                        os.write(rline);
569→                        os.write("\n");
570→                    }
571→                }
572→            }
573→        } catch (IOException e) {
574→            throw new IOException("Error while writing Clob field. column => " + rsMeta.getColumnName(columnNo));
575→        } finally {
576→            IOException ex = null;
577→            if (os != null) {
578→                try {
579→                    os.close();
