611→    private Connection getConnection(String driverClassName, String url, String user, String password) throws IOException {
612→        Connection con = null;
613→        if (driverClassName != null && driverClassName.length() > 0) {
614→            try {
615→                Class.forName(driverClassName);
616→
617→                Properties info = new Properties();
618→                info.put("user", user);
619→                info.put("password", password);
620→                info.put("connectTimeout", "300000");
