 40→    @Override
 41→    protected Map<String, Object> parse(BufferedReader reader) throws IOException {
 42→        String line="";
 43→        //종료 체크용 카운트
 44→        int waitCount = 0;
 45→        String startStr="";
 46→        String endStr="";
 47→        while (isRun) {
 48→            try {
 49→
 50→                //byte X -> char
 51→                line = reader.readLine();
 52→                if(line != null) {
 53→                    waitCount=0;
 54→                    //TODO String dumpFormat,
 55→                    Map<String, Object> record = new HashMap<>();
 56→
 57→                    //dumpFormat에 따라 체크하는 텍스트를 지정해준다.
 58→                    if(dumpFormat.equals("konan")){
 59→                        startStr = "[%productCode%]";
 60→                        //endStr= "[%modifyDate%]";
 61→                        endStr= "[%feeMallType%]";
 62→//                        endStr = "[%quickTime%]"; // [FASTCAT-1211] 상품 데이터 개선 3.0 관련 미링크 협력사 상품 API 필드
 63→                    }else if(dumpFormat.equals("ndjson")){
 64→                        startStr = "{\"productCode\":";
 65→                        //endStr = "\"modifyDate\":";
 66→                        endStr = "\"feeMallType\":";
 67→//                        endStr = "\"quickTime\":"; // [FASTCAT-1211] 상품 데이터 개선 3.0 관련 미링크 협력사 상품 API 필드
 68→                    }
 69→
 70→                    //추후 개행문자로 구분하도록 수정 예정
 71→                    //시작,끝 필드텍스트가 모두 포함되어 있으면 dumpFormat에 따라 ndjson 변환 혹은 그대로 반환
 72→                    if(line.contains(startStr) && line.contains(endStr)) {
 73→
 74→                        if(dumpFormat.equals("konan")){
 75→                            record = gson.fromJson(Utils.convertKonanToNdJson(line), entryType);
 76→                        }else if(dumpFormat.equals("ndjson")){
 77→                            record = gson.fromJson(line, entryType);
 78→                        }
 79→
 80→                        // 비정상 상품 ROW 이후 정상 상품ROW가 읽혔을 때, sb 초기화
 81→                        if(sb.length() > 0) sb.setLength(0);
 82→
 83→                    }else{
 84→                        //정상적인 상품 ROW가 아니면 StringBuilder에 append
 85→                        logger.debug("append line : {}", line);
 86→                        sb.append(line);
 87→                    }
 88→
 89→                    //append된 StringBuilder가 시작, 끝 텍스트를 포함하고 있으면 반환 후 StringBuilder 초기화
 90→                    if(sb.toString().contains(startStr) && sb.toString().contains(endStr)) {
 91→                        logger.debug("sb : {}", sb.toString());
 92→
 93→                        if(dumpFormat.equals("konan")){
 94→                            record = gson.fromJson(Utils.convertKonanToNdJson(sb.toString()), entryType);
 95→                        }else if(dumpFormat.equals("ndjson")){
 96→                            record = gson.fromJson(sb.toString(), entryType);
 97→                        }
 98→                        sb.setLength(0);
 99→                    }else if(sb.length() > startStr.length() && sb.toString().indexOf(startStr) != 0) {
100→                        //문서 ROW의 시작은 항상 상품코드이므로 상품코드가 먼저 시작되지 않았다면 초기화
101→                        //sb.length 체크 이유는 상품코드 텍스트가 짤렸을때 초기화 되는것을 방지( ex. [%PRODU  )
102→                        logger.debug("reset sb : {} ", sb.toString());
103→                        sb.setLength(0);
104→                    }
105→
106→                    return record;
107→                }else{
108→                    //대기 상태가 연속으로 X회 이상이면 반복 중지
109→                    // FIXME rsync 전송이 갑자기 느려져서 20초간 한문서도 전송받지 못하거나
110→                    // 그외 어떤 이유(시스템 부하)로 잠시 멈출때는 전송완료와 구별하지 못함.
111→                    if(waitCount > 20) {
112→                        stop();
113→                    }
114→                    logger.info(("wait"));
115→                    waitCount++;
116→                    Thread.sleep(1000);
117→                }
118→            }catch(Exception e) {
119→                logger.error("parsing error : line = {}, \nconvert = {}, \nsb = {}", line, Utils.convertKonanToNdJson(line), sb.toString());
120→                logger.error("{}", e);
121→                // 에러 발생 시 sb 에 쌓인 데이터 제거
122→                if(sb.length() > 0) sb.setLength(0);
123→//                logger.error("parsing error : line= " + line, e);
124→            }
125→        }
126→        throw new IOException("EOF");
127→    }
