11→@Component
12→public class IndexJobManager {
13→    private static Logger logger = LoggerFactory.getLogger(IndexJobManager.class);
14→    private ConcurrentHashMap<UUID, Job> jobs = new ConcurrentHashMap<>();
15→
16→    public Job remove(UUID id) {
17→        Job job = jobs.get(id);
18→        if (job != null && !"RUNNING".equalsIgnoreCase(job.getStatus())) {
19→            jobs.remove(id);
20→        } else {
21→            job = null;
22→        }
23→        return job;
24→    }
25→
26→    public List<UUID> getIds() {
27→        List<UUID> ids = new ArrayList<>();
28→        Iterator<UUID> iterator = jobs.keySet().iterator();
29→        while (iterator.hasNext()) {
30→            ids.add(iterator.next());
31→        }
32→        return ids;
33→    }
34→
35→    public Job stop(UUID id) {
36→        Job job = jobs.get(id);
37→
38→        if (job == null) {
39→            job = new Job();
40→            job.setId(id);
41→            job.setError("존재하지 않는 ID 입니다.");
42→        } else if (job != null && "RUNNING".equalsIgnoreCase(job.getStatus())) {
43→            logger.info("현재 색인 중인 잡을 종료합니다.");
44→        } else {
45→            job.setError("JOB의 현재 상태를 알 수 없습니다. 종료합니다.");
46→        }
47→
48→        job.setStopSignal(true);
49→        job.setStatus("STOP");
50→
51→        return job;
52→    }
53→
54→    public Job status(UUID id) {
55→        return jobs.get(id);
56→    }
57→
58→    public Job start(String action, Map<String, Object> payload) {
59→        UUID id = genId();
60→        Job job = new Job();
61→        job.setId(id);
62→        job.setRequest(payload);
63→        job.setAction(action);
64→        jobs.put(id, job);
65→        logger.info("job ID: {}, {}", id.toString(), action);
66→        if ("FULL_INDEX".equalsIgnoreCase(action)) {
67→            new Thread(new IndexJobRunner(job)).start();
68→        }
69→        return job;
70→    }
71→
72→    private UUID genId() {
73→        UUID id = UUID.randomUUID();
74→        while (true) {
75→            if (jobs.containsKey(id)) {
76→                id = UUID.randomUUID();
77→            } else {
78→                break;
79→            }
80→        }
81→        return id;
82→    }
